package kvhttp

import java.io.IOException
import java.io.InputStream
import java.io.OutputStream

class Request(val method: String, val target: String, val body: ByteArray)

class Response(
    val status: Int,
    val body: ByteArray = EMPTY,
    val headers: List<Pair<String, String>> = emptyList(),
) {
    companion object {
        private val EMPTY = ByteArray(0)

        fun empty(status: Int, vararg headers: Pair<String, String>) = Response(status, headers = headers.toList())

        fun text(status: Int, body: String, contentType: String = "text/plain; charset=utf-8") =
            Response(status, body.toByteArray(Charsets.UTF_8), listOf("Content-Type" to contentType))
    }
}

/** Limits applied while reading a request. */
data class Limits(
    val maxHeaderBytes: Int = 64 * 1024,
    val maxBodyBytes: Int = 1024 * 1024,
)

/** Outcome of reading one request off a connection. */
sealed interface ReadResult {
    data class Ok(val request: Request) : ReadResult

    /** The request was malformed; send [response] instead of routing. */
    data class Error(val response: Response) : ReadResult

    /** The peer went away or timed out; nothing to answer. */
    data object Closed : ReadResult
}

fun reasonPhrase(status: Int): String = when (status) {
    200 -> "OK"
    201 -> "Created"
    204 -> "No Content"
    400 -> "Bad Request"
    404 -> "Not Found"
    405 -> "Method Not Allowed"
    408 -> "Request Timeout"
    411 -> "Length Required"
    413 -> "Content Too Large"
    431 -> "Request Header Fields Too Large"
    500 -> "Internal Server Error"
    501 -> "Not Implemented"
    505 -> "HTTP Version Not Supported"
    else -> "Unknown"
}

private const val CHUNK_SIZE = 16 * 1024
private val HEADER_END = byteArrayOf('\r'.code.toByte(), '\n'.code.toByte(), '\r'.code.toByte(), '\n'.code.toByte())

private fun fail(status: Int) = ReadResult.Error(Response.empty(status))

/** Index of [HEADER_END] in buf[0, size) starting at [from], or -1. */
private fun findHeaderEnd(buf: ByteArray, size: Int, from: Int): Int {
    for (i in from..size - HEADER_END.size) {
        if (buf[i] == HEADER_END[0] && buf[i + 1] == HEADER_END[1] &&
            buf[i + 2] == HEADER_END[2] && buf[i + 3] == HEADER_END[3]
        ) return i
    }
    return -1
}

/** Reads and throws away [remaining] bytes so the peer sees a clean close rather than a reset. */
private fun InputStream.discard(remaining: Long) {
    var left = remaining
    val scratch = ByteArray(CHUNK_SIZE)
    while (left > 0) {
        val n = read(scratch, 0, minOf(scratch.size.toLong(), left).toInt())
        if (n <= 0) return
        left -= n
    }
}

/** Reads one request from [input]. Socket timeouts and resets are reported as [ReadResult.Closed]. */
fun readRequest(input: InputStream, limits: Limits): ReadResult = try {
    parseRequest(input, limits)
} catch (_: IOException) {
    ReadResult.Closed
}

private fun parseRequest(input: InputStream, limits: Limits): ReadResult {
    var buf = ByteArray(CHUNK_SIZE)
    var size = 0
    var headerEnd = -1

    while (headerEnd < 0) {
        if (size > limits.maxHeaderBytes) return fail(431)
        if (buf.size - size < CHUNK_SIZE) buf = buf.copyOf(buf.size * 2)
        val n = input.read(buf, size, CHUNK_SIZE)
        if (n <= 0) return ReadResult.Closed
        val searchFrom = maxOf(0, size - 3)
        size += n
        headerEnd = findHeaderEnd(buf, size, searchFrom)
    }
    if (headerEnd > limits.maxHeaderBytes) return fail(431)

    val head = String(buf, 0, headerEnd, Charsets.ISO_8859_1)
    val lines = head.split("\r\n")
    val requestLine = lines.first()

    // request-line = method SP request-target SP HTTP-version
    val sp1 = requestLine.indexOf(' ')
    val sp2 = if (sp1 < 0) -1 else requestLine.indexOf(' ', sp1 + 1)
    if (sp2 < 0 || sp1 == 0 || sp2 == sp1 + 1) return fail(400)
    val version = requestLine.substring(sp2 + 1)
    if (!version.startsWith("HTTP/1.")) return fail(if (version.startsWith("HTTP/")) 505 else 400)

    val method = requestLine.substring(0, sp1)
    val target = requestLine.substring(sp1 + 1, sp2)

    var contentLength: Long? = null
    for (line in lines.drop(1)) {
        val colon = line.indexOf(':')
        if (colon <= 0) return fail(400)
        val name = line.substring(0, colon)
        val value = line.substring(colon + 1).trim(' ', '\t')

        when {
            name.equals("Content-Length", ignoreCase = true) -> {
                if (value.isEmpty() || !value.all { it in '0'..'9' }) return fail(400)
                val len = value.toLongOrNull() ?: return fail(400)
                if (contentLength != null && contentLength != len) return fail(400)
                contentLength = len
            }
            name.equals("Transfer-Encoding", ignoreCase = true) -> return fail(501)
        }
    }

    val length = contentLength ?: 0L
    val bodyStart = headerEnd + HEADER_END.size
    val already = size - bodyStart
    if (length > limits.maxBodyBytes) {
        if (already < length) input.discard(length - already)
        return fail(413)
    }

    val body = ByteArray(length.toInt())
    var filled = minOf(already, body.size)
    System.arraycopy(buf, bodyStart, body, 0, filled)
    while (filled < body.size) {
        val n = input.read(body, filled, body.size - filled)
        if (n <= 0) return ReadResult.Closed // truncated body: peer is gone
        filled += n
    }
    return ReadResult.Ok(Request(method, target, body))
}

/** Writes the full response. Throws [IOException] if the peer went away. */
fun writeResponse(output: OutputStream, response: Response) {
    val head = buildString {
        append("HTTP/1.1 ").append(response.status).append(' ').append(reasonPhrase(response.status)).append("\r\n")
        for ((name, value) in response.headers) append(name).append(": ").append(value).append("\r\n")
        if (response.status != 204) append("Content-Length: ").append(response.body.size).append("\r\n")
        append("Connection: close\r\n\r\n")
    }
    output.write(head.toByteArray(Charsets.ISO_8859_1))
    if (response.body.isNotEmpty()) output.write(response.body)
    output.flush()
}

package kvhttp

import java.util.concurrent.ConcurrentSkipListMap

/**
 * Thread-safe in-memory key/value store. Keys are kept in ascending order so
 * listing needs no extra sort. Stored arrays are never mutated after insertion,
 * so readers can send them without copying.
 */
class KvStore {
    private val map = ConcurrentSkipListMap<String, ByteArray>()

    /** Returns true if the key was newly inserted, false if it replaced a value. */
    fun put(key: String, value: ByteArray): Boolean = map.put(key, value) == null

    operator fun get(key: String): ByteArray? = map[key]

    /** Returns true if the key existed. */
    fun remove(key: String): Boolean = map.remove(key) != null

    /** Keys in ascending order (keys are ASCII, so this is byte-wise order). */
    fun keys(): List<String> = map.keys.toList()
}

package kvhttp

import java.io.BufferedOutputStream
import java.io.IOException
import java.net.InetAddress
import java.net.InetSocketAddress
import java.net.ServerSocket
import java.net.Socket
import java.util.concurrent.Executors
import kotlin.system.exitProcess

private const val IO_TIMEOUT_MS = 30_000
private val LIMITS = Limits()

private fun serveConnection(client: Socket, router: Router) {
    client.use { socket ->
        socket.tcpNoDelay = true
        // Don't let an idle or stalled client pin a thread forever.
        socket.soTimeout = IO_TIMEOUT_MS
        try {
            val response = when (val result = readRequest(socket.getInputStream(), LIMITS)) {
                is ReadResult.Ok -> try {
                    router.handle(result.request)
                } catch (e: Exception) {
                    System.err.println("handler failed: $e")
                    Response.empty(500)
                }
                is ReadResult.Error -> result.response
                ReadResult.Closed -> null
            }
            if (response != null) {
                writeResponse(BufferedOutputStream(socket.getOutputStream(), 64 * 1024), response)
            }
            // Half-close so the client reads the full response before the FIN.
            socket.shutdownOutput()
        } catch (_: IOException) {
            // Peer went away; nothing more to do.
        }
    }
}

private fun parsePort(s: String): Int? = s.toIntOrNull()?.takeIf { it in 1..65535 && s.all(Char::isDigit) }

fun main(args: Array<String>) {
    if (args.size != 1) {
        System.err.println("usage: app <port>")
        exitProcess(2)
    }
    val port = parsePort(args[0]) ?: run {
        System.err.println("invalid port: ${args[0]}")
        exitProcess(2)
    }

    val router = Router(KvStore())
    val listener = try {
        ServerSocket().apply {
            reuseAddress = true
            bind(InetSocketAddress(InetAddress.getLoopbackAddress(), port), 1024)
        }
    } catch (e: IOException) {
        System.err.println("fatal: cannot listen on port $port: ${e.message}")
        exitProcess(1)
    }

    // One virtual thread per connection: connections are short-lived and blocking I/O is simplest.
    Executors.newVirtualThreadPerTaskExecutor().use { executor ->
        listener.use {
            while (true) {
                val client = try {
                    listener.accept()
                } catch (e: IOException) {
                    System.err.println("accept failed: ${e.message}")
                    Thread.sleep(10)
                    continue
                }
                executor.execute { serveConnection(client, router) }
            }
        }
    }
}

package kvhttp

private const val KV_PREFIX = "/kv/"
private const val MAX_KEY_LENGTH = 64

private fun isValidKey(key: String): Boolean =
    key.length in 1..MAX_KEY_LENGTH &&
        key.all { it in 'A'..'Z' || it in 'a'..'z' || it in '0'..'9' || it == '_' || it == '-' }

private fun methodNotAllowed(allow: String) = Response.empty(405, "Allow" to allow)

/** Maps requests onto the key/value API described in SPEC.md. */
class Router(private val store: KvStore) {

    fun handle(request: Request): Response {
        val path = request.target
        return when {
            path == "/health" ->
                if (request.method == "GET") Response.text(200, "ok") else methodNotAllowed("GET")
            path == "/kv" ->
                if (request.method == "GET") listKeys() else methodNotAllowed("GET")
            path.startsWith(KV_PREFIX) -> {
                val key = path.removePrefix(KV_PREFIX)
                if (isValidKey(key)) handleKey(request, key) else Response.empty(400)
            }
            else -> Response.empty(404)
        }
    }

    private fun handleKey(request: Request, key: String): Response = when (request.method) {
        "GET" -> store[key]
            ?.let { Response(200, it, listOf("Content-Type" to "application/octet-stream")) }
            ?: Response.empty(404)
        "PUT" -> Response.empty(if (store.put(key, request.body)) 201 else 200)
        "DELETE" -> Response.empty(if (store.remove(key)) 204 else 404)
        else -> methodNotAllowed("GET, PUT, DELETE")
    }

    // Keys are restricted to [A-Za-z0-9_-], so no JSON escaping is needed.
    private fun listKeys(): Response =
        Response.text(200, store.keys().joinToString(",", "[", "]") { "\"$it\"" }, "application/json")
}
